sys_script_include.script:
var commit_update_set = Class.create();
commit_update_set.prototype = {
    commitUpdateSet: function() {


let commitInProgress = false;


    if (commitInProgress) return;

    // Get the update set ID dynamically (replace with your method to fetch the ID)
    const updateSetId = "6b2ea2e4838ed2109a4b66d0deaad303";

    if (!updateSetId) {
        gs.log("Log from Commit Update Set"+"Update Set ID is missing.");
        return;
    }

    commitInProgress = true;
    gs.log("Log from Commit Update Set"+"Starting commit for Update Set:"+ updateSetId);

    const ajaxHelper = new GlideAjax('com.glide.update.UpdateSetCommitAjaxProcessor');
    ajaxHelper.addParam('sysparm_type', 'commitRemoteUpdateSet');
    ajaxHelper.addParam('sysparm_remote_updateset_sys_id', updateSetId);
    ajaxHelper.getXMLAnswer((response) => {
        commitInProgress = false;

        if (!response) {
            gs.error("Log from Commit Update Set"+"Commit failed: No response received.");
            return;
        }

        gs.log("Log from Commit Update Set"+"Commit response:"+ response);

        // Optional: Show success message or handle post-commit actions
        gs.log("Log from Commit Update Set"+"Update Set committed successfully!");
    });





    },

    type: 'commit_update_set'
};
